369	/* Re-query the window size and update the internal character grid if changed.
370	 */
371	static Bool
372	resize_grid (p_state *state)
373	{
374	  int ow = state->grid_width;
375	  int oh = state->grid_height;
376	  p_cell *ocells = state->cells;
377	  int x, y;
378	
379	  XGetWindowAttributes (state->dpy, state->window, &state->xgwa);
380	
381	  /* Would like to ensure here that
382	     state->char_height * state->scale <= state->xgwa.height
383	     but changing scale requires regenerating the bitmaps. */
384	
385	  state->grid_width  = ((state->xgwa.width - state->xmargin * 2) /
386	                        (state->char_width  * state->scale));
387	  state->grid_height = ((state->xgwa.height - state->ymargin * 2) /
388	                        (state->char_height * state->scale));
389	
390	  if (state->grid_width  < 2) state->grid_width  = 2;
391	  if (state->grid_height < 2) state->grid_height = 2;
392	
393	  if (ow == state->grid_width &&
394	      oh == state->grid_height)
395	    return False;
396	
397	  state->cells = (p_cell *) calloc (sizeof(p_cell),
398	                                    state->grid_width * state->grid_height);
399	
400	  for (y = 0; y < state->grid_height; y++)
401	    {
402	      for (x = 0; x < state->grid_width; x++)
403	        {
404	          p_cell *ncell = &state->cells [state->grid_width * y + x];
405	          if (x < ow && y < oh)
406	            *ncell = ocells [ow * y + x];
407	          ncell->changed = True;
408	        }
409	    }
410	
411	  if (state->cursor_x >= state->grid_width)
412	    state->cursor_x = state->grid_width-1;
413	  if (state->cursor_y >= state->grid_height)
414	    state->cursor_y = state->grid_height-1;
415	
416	  free (ocells);
417	  return True;
418	}
