723	static void
724	char_to_pixmap (p_state *state, p_char *pc, unsigned long c,
725	                Bool invert_p, Bool symbol_p)
726	{
727	  Pixmap p = 0;
728	  GC gc;
729	# ifdef FUZZY_BORDER
730	  Pixmap p2 = 0;
731	  GC gc2;
732	# endif /* FUZZY_BORDER */
733	  int from, to;
734	  int x1, y;
735	  XImage *font_bits = (symbol_p ? state->sym_font_bits : state->font_bits);
736	
737	  int safe_width = state->char_width + 1;
738	
739	  int width  = state->scale * state->char_width;
740	  int height = state->scale * state->char_height;
741	
742	  gc = state->gc1;
743	  p = XCreatePixmap (state->dpy, state->window, width, height, 1);
744	  XFillRectangle (state->dpy, p, state->gc0, 0, 0, width, height);
745	# ifdef FUZZY_BORDER
746	  gc2 = state->gc2;
747	  p2 = XCreatePixmap (state->dpy, state->window, width, height, 1);
748	  XFillRectangle (state->dpy, p2, state->gc0, 0, 0, width, height);
749	# endif /* FUZZY_BORDER */
750	
751	  from = safe_width * c;
752	  to =   safe_width * (c + 1);
753	
754	# if 0
755	  if (c > 75 && c < 150)
756	    {
757	      printf ("\n=========== %lu (%c)\n", c, (char) c);
758	      for (y = 0; y < state->char_height; y++)
759	        {
760	          for (x1 = from; x1 < to; x1++)
761	            printf (XGetPixel (font_bits, x1, y) ? "* " : ". ");
762	          printf ("\n");
763	        }
764	    }
765	# endif
766	
767	  pc->blank_p = !invert_p;
768	  for (y = 0; y < state->char_height; y++)
769	    for (x1 = from; x1 < to; x1++)
770	      {
771	        unsigned long pix = XGetPixel (font_bits, x1, y);
772	        if (invert_p) pix = !pix;
773	        if (pix)
774	          {
775	            int xoff = state->scale / 2;
776	            int x2;
777	            for (x2 = x1; x2 < to; x2++)
778	              {
779	                pix = XGetPixel (font_bits, x2, y);
780	                if (invert_p) pix = !pix;
781	                if (!pix)
782	                  break;
783	              }
784	            x2--;
785	            XDrawLine (state->dpy, p, gc,
786	                       (x1 - from) * state->scale + xoff, y * state->scale,
787	                       (x2 - from) * state->scale + xoff, y * state->scale);
788	# ifdef FUZZY_BORDER
789	            XDrawLine (state->dpy, p2, gc2,
790	                       (x1 - from) * state->scale + xoff, y * state->scale,
791	                       (x2 - from) * state->scale + xoff, y * state->scale);
792	# endif /* FUZZY_BORDER */
793	            x1 = x2;
794	            pc->blank_p = False;
795	          }
796	      }
797	
798	  pc->pixmap = p;
799	# ifdef FUZZY_BORDER
800	  pc->pixmap2 = p2;
801	# endif /* FUZZY_BORDER */
802	
803	# ifdef FUZZY_BORDER
804	  pc->cache = 0;
805	  if (get_boolean_resource (state->dpy, "cache", "Cache"))
806	    {
807	      /* Cache every possible frame of this character's fade in a pixmap,
808	         because XSetClipMask has become *incredibly* fucking slow on
809	         "modern" X11 systems (e.g. Raspbian 11.)  I blame compositors. */
810	
811	      int st;
812	      pc->cache = XCreatePixmap (state->dpy, state->window,
813	                                 width * state->ticks, height,
814	                                 state->xgwa.depth);
815	      for (st = 0; st < state->ticks; st++)
816	        {
817	          int tx = st * width;
818	          int ty = 0;
819	          GC gc1 = state->gcs[st];
820	          GC gc2 = ((st + 2) < state->ticks
821	                    ? state->gcs[st + 2]
822	                    : 0);
823	          GC gc3 = (gc2 ? gc2 : gc1);
824	          if (gc3)
825	            XCopyPlane (state->dpy, pc->pixmap, pc->cache, gc3,
826	                        0, 0, width, height, tx, ty, 1L);
827	          if (gc2)
828	            {
829	              XSetClipMask (state->dpy, gc1, pc->pixmap2);
830	              XSetClipOrigin (state->dpy, gc1, tx, ty);
831	              XFillRectangle (state->dpy, pc->cache, gc1,
832	                              tx, ty, width, height);
833	              XSetClipMask (state->dpy, gc1, None);
834	            }
835	        }
836	    }
837	# endif /* FUZZY_BORDER */
838	}
