893	static void
894	decay (p_state *state)
895	{
896	  int x, y;
897	  for (y = 0; y < state->grid_height; y++)
898	    for (x = 0; x < state->grid_width; x++)
899	      {
900	        p_cell *cell = &state->cells[state->grid_width * y + x];
901	        if (cell->state == FLARE)
902	          {
903	            cell->state = NORMAL;
904	            cell->changed = True;
905	          }
906	        else if (cell->state >= FADE)
907	          {
908	            cell->state++;
909	            if (cell->state >= state->ticks)
910	              {
911	                cell->state = BLANK;
912	                cell->c = ' ';
913	              }
914	            cell->changed = True;
915	          }
916	      }
917	}
