920	static void
921	print_char (p_state *state, int c)
922	{
923	  int x, y;
924	  ansi_tty *tty = state->tty;
925	  ansi_tty_print (tty, c);
926	
927	  for (y = 0; y < tty->height; y++)
928	    for (x = 0; x < tty->width; x++)
929	      {
930	        tty_char *tcell = &tty->grid [tty->width * y + x];
931	        p_cell   *cell  = &state->cells [state->grid_width * y + x];
932	        Bool inv_p = tcell->flags & (TTY_BOLD | TTY_ITALIC | TTY_INVERSE);
933	        Bool sym_p = tcell->flags & (TTY_SYMBOLS);
934	        unsigned char latin1 = 0;
935	        p_char *pc;
936	
937	        if (tty->inverse_p) inv_p = !inv_p;
938	
939	        if ( cell->c == 0)  cell->c = ' ';
940	        if (tcell->c == 0) tcell->c = ' ';
941	
942	        if (tcell->c <= 128)
943	          latin1 = tcell->c;
944	        else
945	          {
946	            /* Convert non-ASCII Unicode to closest Latin1. */
947	            char utf8[10];
948	            if (utf8_encode (tcell->c, utf8, sizeof(utf8)-1))
949	              {
950	                char *s = utf8_to_latin1 (utf8, FALSE);
951	                if (s)
952	                  {
953	                    latin1 = s[0];
954	                    free (s);
955	                  }
956	              }
957	          }
958	
959	        if (!latin1) latin1 = ' ';
960	
961	        pc = (cell->symbol_p
962	              ? (inv_p ? state->sichars[cell->c] : state->schars[cell->c])
963	              : (inv_p ?  state->ichars[cell->c] :  state->chars[cell->c]));
964	
965	        if (!pc->blank_p &&
966	            latin1 == ' ' &&
967	            !inv_p)
968	          {
969	            /* Replacing existing character with a blank:
970	               fade out the previous character. */
971	            if (cell->state == FLARE || cell->state == NORMAL)
972	              cell->state = FADE;
973	            cell->changed = True;
974	          }
975	        else if (cell->c != tcell->c ||
976	                 cell->state >= FADE ||
977	                 cell->invert_p != inv_p ||
978	                 cell->symbol_p != sym_p)
979	          {
980	            /* Adding a new character: flare it in. */
981	            cell->invert_p = inv_p;
982	            cell->symbol_p = sym_p;
983	            /* cell->state = FLARE;  -- Looks bad when scrolling */
984	            cell->state = NORMAL;
985	            cell->changed = True;
986	            cell->c = latin1;
987	          }
988	      }
989	
990	  /* If the cursor has moved, turn it on and flare it. */
991	  if (state->cursor_x != tty->x ||
992	      state->cursor_y != tty->y)
993	    {
994	      p_cell *oc = &state->cells [state->grid_width * state->cursor_y +
995	                                  state->cursor_x];
996	      p_cell *nc = &state->cells [state->grid_width * tty->y +
997	                                  tty->x];
998	      oc->changed = True;
999	      nc->changed = True;
1000	
1001	      /* If the new cell is already fading out, do not bring its old
1002	         character back underneath this new cursor. */
1003	      if (nc->state >= FADE)
1004	        nc->c = ' ';
1005	      nc->state = FLARE;
1006	      state->cursor_x = tty->x;
1007	      state->cursor_y = tty->y;
1008	      set_cursor (state, True);
1009	    }
1010	}
